/**
 * synthetic.js — generate frames whose correct answer is known by construction.
 *
 * Used by the tests, because a metric extractor validated only against real
 * photographs is validated against a guess: nobody knows the true variance of
 * the Laplacian of a museum vessel. A frame blurred *by construction* must
 * score lower than the frame it was blurred from, and a frame with 10% of its
 * pixels pinned at 255 must report 10% clipping.
 *
 * Also used by the demo page, so what the browser measures is generated by the
 * same code the test suite exercises rather than by a second implementation
 * that could drift.
 */

/** Deterministic PRNG, so a failure is reproducible. */
export function rng(seed = 1) {
  let s = seed >>> 0;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

/** Uniform RGBA frame. */
export function blank(width, height, [r, g, b] = [128, 128, 128]) {
  const d = new Uint8ClampedArray(width * height * 4);
  for (let p = 0; p < d.length; p += 4) {
    d[p] = r; d[p + 1] = g; d[p + 2] = b; d[p + 3] = 255;
  }
  return d;
}

/** Uniform grey. No clipping anywhere, and a flat lighting signature. */
export function flat(width, height, level = 128) {
  return blank(width, height, [level, level, level]);
}

/**
 * High-frequency noise: the sharpest thing a frame can contain, and therefore
 * the upper reference point for sharpness.
 */
export function noisy(width, height, { seed = 1, amplitude = 90, base = 128 } = {}) {
  const rand = rng(seed);
  const d = new Uint8ClampedArray(width * height * 4);
  for (let i = 0, p = 0; i < width * height; i++, p += 4) {
    const v = base + (rand() - 0.5) * 2 * amplitude;
    d[p] = v; d[p + 1] = v; d[p + 2] = v; d[p + 3] = 255;
  }
  return d;
}

/** Hard-edged checkerboard: sharp, but structured rather than random. */
export function checker(width, height, { square = 16, dark = 40, light = 215 } = {}) {
  const d = new Uint8ClampedArray(width * height * 4);
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const v = (((x / square) | 0) + ((y / square) | 0)) % 2 ? light : dark;
      const p = (y * width + x) * 4;
      d[p] = v; d[p + 1] = v; d[p + 2] = v; d[p + 3] = 255;
    }
  }
  return d;
}

/**
 * Box blur. Blurring must lower the sharpness score — that is the property
 * under test, and it holds regardless of what the frame contains.
 */
export function blur(rgba, width, height, radius = 2) {
  const out = new Uint8ClampedArray(rgba.length);
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let n = 0;
      const acc = [0, 0, 0];
      for (let dy = -radius; dy <= radius; dy++) {
        for (let dx = -radius; dx <= radius; dx++) {
          const sy = y + dy, sx = x + dx;
          if (sy < 0 || sy >= height || sx < 0 || sx >= width) continue;
          const q = (sy * width + sx) * 4;
          acc[0] += rgba[q]; acc[1] += rgba[q + 1]; acc[2] += rgba[q + 2];
          n++;
        }
      }
      const p = (y * width + x) * 4;
      out[p] = acc[0] / n; out[p + 1] = acc[1] / n; out[p + 2] = acc[2] / n; out[p + 3] = 255;
    }
  }
  return out;
}

/**
 * Pin an exact fraction of pixels to a value, so the expected clipping fraction
 * is known precisely rather than approximately.
 */
export function clipPixels(rgba, width, height, { fraction, value = 255, channels = [0, 1, 2] }) {
  const out = Uint8ClampedArray.from(rgba);
  const n = Math.round(width * height * fraction);
  for (let i = 0; i < n; i++) {
    const p = i * 4;
    for (const c of channels) out[p + c] = value;
  }
  return out;
}
